'use client';

import type { Variants } from 'motion/react';
import { AnimatePresence, motion, useAnimation, cubicBezier, type Transition } from 'motion/react';
import type { LucideProps } from 'lucide-react';
import React, { forwardRef, useCallback, useRef, useEffect, useState, Fragment } from 'react';
import { cn } from '@/lib/utils';

interface ProjectsIconProps extends LucideProps {}

const SQUARE_VARIANTS: Variants = {
  normal: {
    scale: 1,
    transition: { duration: 0.2 },
  },
  animate: (custom: number) => ({
    scale: [1, 1.32, 1],
    transition: {
      duration: 0.5,
      delay: custom * 0.08,
      ease: [0.34, 1.56, 0.64, 1],
    },
  }),
}

const SQUARES = [
  { x: 3, y: 3 },
  { x: 14, y: 3 },
  { x: 3, y: 14 },
  { x: 14, y: 14 },
]

const ProjectsIcon = forwardRef<SVGSVGElement, ProjectsIconProps>(
  (
    { size = 28, className, onMouseEnter, onMouseLeave, onPointerDown, color = 'currentColor', strokeWidth = 2, ...rest },
    ref,
  ) => {
    const controls = useAnimation()

    const handleMouseEnter = useCallback(
      (e: React.MouseEvent<SVGSVGElement>) => {
        controls.start('animate')
        onMouseEnter?.(e)
      },
      [controls, onMouseEnter],
    )

    const handleMouseLeave = useCallback(
      (e: React.MouseEvent<SVGSVGElement>) => {
        controls.start('normal')
        onMouseLeave?.(e)
      },
      [controls, onMouseLeave],
    )

    const handlePointerDown = useCallback(
      async (e: React.PointerEvent<SVGSVGElement>) => {
        if (e.pointerType !== 'mouse') {
          controls.start('normal')
          requestAnimationFrame(() => {
            controls.start('animate')
          })
        }
        onPointerDown?.(e)
      },
      [controls, onPointerDown],
    )

    return (
      <svg
        ref={ref}
        fill="none"
        height={size}
        width={size}
        stroke={color}
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeWidth={strokeWidth}
        viewBox="0 0 24 24"
        xmlns="http://www.w3.org/2000/svg"
        className={className}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        onPointerDown={handlePointerDown}
        {...(rest as any)}
      >
        {SQUARES.map((sq, i) => (
          <motion.rect
            key={`${sq.x}-${sq.y}`}
            animate={controls}
            custom={i}
            initial="normal"
            variants={SQUARE_VARIANTS}
            x={sq.x}
            y={sq.y}
            width="7"
            height="7"
            rx="1.5"
            style={{ transformBox: 'fill-box', transformOrigin: 'center' }}
          />
        ))}
      </svg>
    )
  },
)


const MAILBOX_FLAG_VARIANTS: Variants = {
  normal: { rotate: 0, transition: { type: 'spring', stiffness: 300, damping: 18 } },
  animate: { rotate: -90, transition: { type: 'spring', stiffness: 280, damping: 12, mass: 1 } },
};

const MailboxMotion = forwardRef<SVGSVGElement, LucideProps>(
  ({ size = 24, className, onMouseEnter, onMouseLeave, onPointerDown, color = 'currentColor', strokeWidth = 2, ...rest }, ref) => {
    const controls = useAnimation();
    const svgRef = useRef<SVGSVGElement>(null);

    const setRefs = useCallback(
      (node: SVGSVGElement | null) => {
        (svgRef as React.MutableRefObject<SVGSVGElement | null>).current = node;
        if (typeof ref === 'function') ref(node);
        else if (ref) (ref as React.MutableRefObject<SVGSVGElement | null>).current = node;
      },
      [ref]
    );

    const trigger = useCallback(() => controls.start('animate'), [controls]);
    const reset = useCallback(() => controls.start('normal'), [controls]);

    const handleMouseEnter = useCallback(
      (e: React.MouseEvent<SVGSVGElement>) => {
        trigger();
        onMouseEnter?.(e);
      },
      [trigger, onMouseEnter]
    );

    const handleMouseLeave = useCallback(
      (e: React.MouseEvent<SVGSVGElement>) => {
        reset();
        onMouseLeave?.(e);
      },
      [reset, onMouseLeave]
    );

    const handlePointerDown = useCallback(
      async (e: React.PointerEvent<SVGSVGElement>) => {
        if (e.pointerType !== 'mouse') {
          reset();
          requestAnimationFrame(trigger);
        }
        onPointerDown?.(e);
      },
      [reset, trigger, onPointerDown]
    );

    return (
      <svg
        ref={setRefs}
        className={cn('overflow-visible', className)}
        fill="none"
        height={size}
        width={size}
        stroke={color}
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeWidth={strokeWidth}
        viewBox="0 0 24 24"
        xmlns="http://www.w3.org/2000/svg"
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        onPointerDown={handlePointerDown}
        {...(rest as any)}
      >
        <path d="M22 17a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V9.5C2 7 4 5 6.5 5H18c2.2 0 4 1.8 4 4v8Z" />
        <motion.path
          animate={controls}
          d="M18 11V9H15"
          initial="normal"
          style={{ transformOrigin: '18px 11px' }}
          variants={MAILBOX_FLAG_VARIANTS}
        />
        <path d="M6.5 5C9 5 11 7 11 9.5V17a2 2 0 0 1-2 2" />
        <line x1="6" x2="7" y1="10" y2="10" />
      </svg>
    );
  }
);


