interface KeyboardIconProps extends LucideProps {}
const Keyboard_KEYBOARD_PATHS = [
  { id: "key1", d: "M10 8h.01" },
  { id: "key2", d: "M12 12h.01" },
  { id: "key3", d: "M14 8h.01" },
  { id: "key4", d: "M16 12h.01" },
  { id: "key5", d: "M18 8h.01" },
  { id: "key6", d: "M6 8h.01" },
  { id: "key7", d: "M7 16h10" },
  { id: "key8", d: "M8 12h.01" },
];

const KeyboardIcon = forwardRef<SVGSVGElement, KeyboardIconProps>(
  ({ size = 28, className, onMouseEnter, onMouseLeave, onPointerDown, color = 'currentColor', strokeWidth = 2, ...rest }, ref) => {
    const [isHovered, setIsHovered] = useState(false);
    const controls = useAnimation();
    const handleMouseEnter = useCallback(
    (e: React.MouseEvent<SVGSVGElement>) => {
      setIsHovered(true);
      onMouseEnter?.(e);
    },
    [onMouseEnter],
  );

    const handleMouseLeave = useCallback(
    (e: React.MouseEvent<SVGSVGElement>) => {
      setIsHovered(false);
      onMouseLeave?.(e);
    },
    [onMouseLeave],
  );

    useEffect(() => {
      const animateKeys = async () => {
        if (isHovered) {
          await controls.start((i) => ({
            opacity: [1, 0.2, 1],
            transition: {
              duration: 1.5,
              times: [0, 0.5, 1],
              delay: i * 0.2 * Math.random(),
              repeat: 1,
              repeatType: "reverse",
            },
          }));
        } else {
          controls.stop();
          controls.set({ opacity: 1 });
        }
      };

      animateKeys();
    }, [isHovered, controls]);
  const handlePointerDown = useCallback(
    async (e: React.PointerEvent<SVGSVGElement>) => {
      if (e.pointerType !== 'mouse') {
        setIsHovered(false);
        requestAnimationFrame(async () => {
          setIsHovered(true);
        });
      }
      onPointerDown?.(e);
    },
    [onPointerDown],
  );


    return (
      <svg
        ref={ref}
        fill="none"
          height={size}
          stroke={color}
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeWidth={strokeWidth}
          viewBox="0 0 24 24"
          width={size}
          xmlns="http://www.w3.org/2000/svg"
        className={className}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        onPointerDown={handlePointerDown}
        {...(rest as any)}
      >
          <rect height="16" rx="2" width="20" x="2" y="4" />
          <AnimatePresence>
            {Keyboard_KEYBOARD_PATHS.map((path, index) => (
              <motion.path
                animate={controls}
                custom={index}
                d={path.d}
                initial={{ opacity: 1 }}
                key={path.id}
              />
            ))}
          </AnimatePresence>
        </svg>
    );
  }
);



