interface PaletteIconProps extends LucideProps {}
const Palette_DASH_LENGTH = 70;
const Palette_DRAW_DURATION = 0.45;
const Palette_DOT_STAGGER = 0.08;

const Palette_DOTS = [
  { cx: 6.5, cy: 12.5 },
  { cx: 8.5, cy: 7.5 },
  { cx: 13.5, cy: 6.5 },
  { cx: 17.5, cy: 10.5 },
];

const Palette_OUTLINE_VARIANTS: Variants = {
  normal: {
    strokeDashoffset: 0,
  },
  animate: {
    strokeDashoffset: [Palette_DASH_LENGTH, 0],
    transition: {
      duration: Palette_DRAW_DURATION,
      ease: [0.65, 0, 0.35, 1],
    },
  },
};

const Palette_DOTS_GROUP_VARIANTS: Variants = {
  normal: {},
  animate: {
    transition: {
      delayChildren: Palette_DRAW_DURATION,
      staggerChildren: Palette_DOT_STAGGER,
    },
  },
};

const Palette_DOT_VARIANTS: Variants = {
  normal: {
    scale: 1,
    transition: { duration: 0.2 },
  },
  animate: {
    // Two keyframes only: motion rejects 3+ keyframes on a spring.
    // Lower damping (10) = weaker restoring force = bigger, slower overshoot
    // before it settles — closer to the ~1.25 peak / softer landing we wanted,
    // versus damping 14 which snapped back to 1 too quickly.
    scale: [0, 1],
    transition: {
      damping: 10,
      stiffness: 300,
      type: "spring",
    },
  },
};

const PaletteIcon = forwardRef<SVGSVGElement, PaletteIconProps>(
  ({ size = 28, className, onMouseEnter, onMouseLeave, onPointerDown, color = 'currentColor', strokeWidth = 2, ...rest }, ref) => {
    const controls = useAnimation();
    const handleMouseEnter = useCallback(
    (e: React.MouseEvent<SVGSVGElement>) => {
      controls.start("animate");
      onMouseEnter?.(e);
    },
    [controls, onMouseEnter],
  );

    const handleMouseLeave = useCallback(
    (e: React.MouseEvent<SVGSVGElement>) => {
      controls.start("normal");
      onMouseLeave?.(e);
    },
    [controls, onMouseLeave],
  );
  const handlePointerDown = useCallback(
    async (e: React.PointerEvent<SVGSVGElement>) => {
      if (e.pointerType !== 'mouse') {
        controls.start("normal");
        requestAnimationFrame(async () => {
          controls.start("animate");
        });
      }
      onPointerDown?.(e);
    },
    [controls, onPointerDown],
  );


    return (
      <svg
        ref={ref}
        fill="none"
          height={size}
          stroke={color}
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeWidth={strokeWidth}
          viewBox="0 0 24 24"
          width={size}
          xmlns="http://www.w3.org/2000/svg"
        className={className}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        onPointerDown={handlePointerDown}
        {...(rest as any)}
      >
          <motion.path
            animate={controls}
            d="M12 2a1 1 0 0 0 0 20l.25 0a1.75 1.75 0 0 0 1.4-2.8l-.3-.4a1.75 1.75 0 0 1 1.4-2.8h2.25a5 5 0 0 0 5-5 10 9 0 0 0-10-9z"
            initial="normal"
            strokeDasharray={Palette_DASH_LENGTH}
            variants={Palette_OUTLINE_VARIANTS}
          />
          <motion.g
            animate={controls}
            initial="normal"
            variants={Palette_DOTS_GROUP_VARIANTS}
          >
            {Palette_DOTS.map((dot) => (
              <motion.circle
                cx={dot.cx}
                cy={dot.cy}
                fill="currentColor"
                key={`${dot.cx}-${dot.cy}`}
                r=".5"
                style={{ transformBox: "fill-box", transformOrigin: "center" }}
                variants={Palette_DOT_VARIANTS}
              />
            ))}
          </motion.g>
        </svg>
    );
  }
);



